import {DIFFICULTIES,POWERS,encodeChallenge,decodeChallenge,challengeKey,summarizeRun,bestRun} from './challenges.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=t=>{const centis=Math.floor(Math.max(0,t)*100);return `${Math.floor(centis/6000).toString().padStart(2,'0')}:${(centis%6000/100).toFixed(2).padStart(5,'0')}`;};
export class FeatureUI {
 constructor(context){Object.assign(this,context);this.prefs={difficulty:'standard',audienceEnabled:true};try{const p=JSON.parse(localStorage.getItem('raidforge-preferences'));if(p&&Object.hasOwn(DIFFICULTIES,p.difficulty))this.prefs={difficulty:p.difficulty,audienceEnabled:p.audienceEnabled!==false};}catch{}
  this.crowd=null;this.seenPowers=new Set();this.practiceCooldown=0;this.lastRecord=null;this.fightContext=null;this.view='forge';
  $$('[data-difficulty]').forEach(b=>b.onclick=()=>{if(this.locked())return;this.prefs.difficulty=b.dataset.difficulty;this.savePreferences();this.render();});
  $('#audience-enabled').onchange=e=>{if(this.locked())return;this.prefs.audienceEnabled=e.target.checked;this.savePreferences();this.render();};
  $('#share-challenge').onclick=()=>this.share();
  $$('[data-power]').forEach(b=>b.onclick=()=>{if(this.getMode()==='live')return;if(!this.arena.applyPower(b.dataset.power,'Practice control — you triggered this'))return;this.practiceCooldown=this.arena.elapsed+12;this.toast(`${POWERS[b.dataset.power].label} activated. Practice controls recharge in 12 seconds.`);this.update();this.arena.canvas.focus({preventScroll:true});});
  this.timer=setInterval(()=>this.update(),250);this.render();
 }
 locked(){return ['playing','paused'].includes(this.arena.mode);}
 savePreferences(){try{localStorage.setItem('raidforge-preferences',JSON.stringify(this.prefs));}catch{}}
 challenge(state=this.getState()){return{version:1,program:state.program,difficulty:this.prefs.difficulty,audienceEnabled:this.prefs.audienceEnabled,author:state.author,mutationAuthor:state.mutationAuthor||'RAIDFORGE',trait:state.trait};}
 beforeStart(){this.arena.difficulty=this.prefs.difficulty;this.arena.audienceEnabled=this.prefs.audienceEnabled;this.practiceCooldown=0;this.crowd=null;this.fightContext=this.challenge();this.seenPowers.clear();}
 render(){const state=this.getState();$('#runs-count').textContent=String(state.battles.length).padStart(2,'0');$('#creator-credit').textContent=`ATTACK DESIGN / ${state.mutationAuthor||'RAIDFORGE'}`;$('#hud-creator').textContent=$('#creator-credit').textContent;$('#audience-enabled').checked=this.prefs.audienceEnabled;$$('[data-difficulty]').forEach(b=>{b.classList.toggle('active',b.dataset.difficulty===this.prefs.difficulty);b.setAttribute('aria-pressed',b.dataset.difficulty===this.prefs.difficulty);});$('#challenge-id').textContent=challengeKey(state.program,this.prefs.difficulty,this.prefs.audienceEnabled);if(this.view==='runs')this.renderRuns();this.update();}
 update(){const fighting=this.arena.mode==='playing'&&!this.arena.preview,live=this.getMode()==='live';$$('[data-difficulty]').forEach(b=>b.disabled=this.locked());$('#audience-enabled').disabled=this.locked();$('#share-challenge').disabled=this.arena.preview;
  const enabled=this.locked()?this.arena.audienceEnabled:this.prefs.audienceEnabled;const cooling=Math.max(0,Math.ceil(this.practiceCooldown-this.arena.elapsed));
  $('#audience-description').textContent=live?'Chat chooses a power every 12 seconds. One vote per viewer; a new command changes your vote. Ties favor shield, then heal.':'Rehearse a power during a fight. These controls are yours; live viewers vote through Twitch chat.';
  for(const b of $$('[data-power]')){b.disabled=live||!fighting||!enabled||cooling>0;const count=this.crowd?.counts?.[b.dataset.power]||0;b.querySelector('.power-count').textContent=live?`${count} ${count===1?'vote':'votes'}`:cooling>0?`Ready in ${cooling}s`:'Try power';b.title=live?`Viewers type ${POWERS[b.dataset.power].command} in Twitch chat`:POWERS[b.dataset.power].description;}
  const active=live&&this.crowd?.active&&fighting&&this.crowd.runId===this.arena.runId;
  $('#audience-round').textContent=!enabled?'POWERS OFF':active?`RESOLVES IN ${Math.max(0,Math.ceil((this.crowd.localEndsAt-performance.now())/1000))}s`:live?'WAITING FOR A FIGHT':'PRACTICE CONTROLS';
  $('#audience-hint').textContent=!enabled?'Pure skill run. Chat powers are disabled.':active?`${this.crowd.total||0} unique voters · the winning power fires automatically.`:live?'Start a fight with the live service connected.':fighting?'One practice power every 12 seconds.':'Enter the arena to rehearse a power.';
 }
 receiveStatus(status){this.crowd={...status,localEndsAt:performance.now()+(status.remainingMs||0)};this.update();}
 receivePower(event){if(event.runId!==this.arena.runId||this.seenPowers.has(event.id)||this.getMode()!=='live')return;this.seenPowers.add(event.id);const count=Number(event.voters)||0;const source=`Chat chose this · ${count} ${count===1?'viewer':'viewers'}`;if(this.arena.applyPower(event.power,source))this.toast(`${POWERS[event.power].label} — voted by ${(event.credits||[]).join(', ')}${count>3?` + ${count-3} more`:''}`);}
 record(result){const challenge=this.fightContext||this.challenge();const key=challengeKey(challenge.program,challenge.difficulty,challenge.audienceEnabled);const previous=bestRun(this.getState().battles,key);const record={...result,id:crypto.randomUUID(),at:new Date().toISOString(),boss:challenge.program.name,creator:challenge.mutationAuthor,challengeKey:key,challenge,summary:summarizeRun(result),newBest:result.won&&(!previous||result.time<previous.time)};this.lastRecord=record;return record;}
 showReport(record=this.lastRecord){if(!record)return;this.lastRecord=record;const summary=record.summary||summarizeRun(record);const difficulty=DIFFICULTIES[record.difficulty]?.label||'Standard';const audience=record.audienceEnabled?'Chat powers on':'Pure skill';$('#run-report').hidden=false;$('#run-report').innerHTML=`<div class="report-top"><div><div class="eyebrow">YOUR RUN / ${esc(difficulty.toUpperCase())}</div><h3>${record.won?'A goose well cooked.':'The legend grows.'}</h3>${record.newBest?'<span class="record-badge">NEW PERSONAL BEST</span>':''}</div><span class="report-rank" title="Run grade">${esc(summary.rank)}</span></div><div class="report-stats"><div><span>TIME</span><b>${clock(record.time)}</b></div><div><span>SCORE</span><b>${summary.score.toLocaleString()}</b></div><div><span>ACCURACY</span><b>${summary.accuracy}%</b></div><div><span>HEARTS LEFT</span><b>${record.health} / 5</b></div></div><div class="report-meta">${esc(record.boss)} · attack design by ${esc(record.creator||'RAIDFORGE')}<br>${esc(audience)} · ${summary.powers} powers · ${summary.dashes} dashes · ${esc(record.challengeKey||'Earlier build')}<br>Personal records are scoped to this ${this.getMode()==='live'?'workshop':'device'} and the same boss + difficulty + power setting.</div><div class="report-actions"><button class="button primary" id="download-run-card">Download scorecard ↓</button><button class="button ghost" id="share-run-challenge">Challenge a friend →</button><button class="button ghost" id="open-run-book">Run book</button></div>`;$('#download-run-card').onclick=()=>this.downloadScorecard(record);$('#share-run-challenge').onclick=()=>this.share(record.challenge||this.challenge());$('#open-run-book').onclick=()=>this.setView('runs');}
 onView(view){this.view=view;if(view==='runs')this.renderRuns();}
 renderRuns(){const records=this.getState().battles;const wins=records.filter(r=>r.won).length;$('#runs-view').innerHTML=`<div class="eyebrow">KEEP A RECORD. SET A CHALLENGE.</div><h2 class="secondary-title">THE RUN BOOK.</h2><p class="secondary-description">Your fights, your progress, your next personal best. Records belong to this ${this.getMode()==='live'?'workshop':'device'}.</p><div class="run-summary"><div><b>${records.length}</b><span>COMPLETED RUNS</span></div><div><b>${wins}</b><span>GOOSE VICTORIES</span></div><div><b>${records.length?Math.round(wins/records.length*100):0}%</b><span>WIN RATE</span></div></div>${records.length?`<div class="run-list">${[...records].reverse().map(r=>{const summary=r.summary||summarizeRun(r);return`<article class="run-item"><span class="run-grade">${esc(summary.rank)}</span><div class="run-item-main"><b>${esc(r.boss)} ${r.newBest?'<span class="record-badge">PB AT THE TIME</span>':''}</b><small>${esc(DIFFICULTIES[r.difficulty]?.label||'Standard')} · ${r.audienceEnabled?'POWERS ON':'PURE SKILL'} · ${esc(new Date(r.at).toLocaleDateString())}<br>${esc(r.challengeKey||'Earlier build')}</small></div><span class="run-item-time">${clock(r.time)}</span><button class="text-button" data-report-id="${esc(r.id)}">Report →</button></article>`;}).join('')}</div>`:'<div class="empty-state"><div class="empty-icon">◇</div><h3>Your first run is waiting.</h3><p>Finish a fight to record your time, accuracy, grade, and creator credits.</p><button class="button primary" id="runs-play">Enter the workshop →</button></div>'}`;if($('#runs-play'))$('#runs-play').onclick=()=>this.setView('forge');$$('[data-report-id]').forEach(b=>b.onclick=()=>{const r=records.find(r=>r.id===b.dataset.reportId);this.setView('forge');this.showReport(r);$('#run-report').scrollIntoView({behavior:'smooth',block:'center'});});}
 share(challenge=this.challenge()){try{const code=encodeChallenge(challenge),url=new URL(location.href);url.search='';url.hash='challenge='+code;const full=url.toString(),key=challengeKey(challenge.program,challenge.difficulty,challenge.audienceEnabled);this.showModal(`<div class="modal-eyebrow">SEND THE ACTUAL BOSS</div><h2>Your monster.<br>Their problem.</h2><div class="challenge-preview"><span class="eyebrow">${esc(key)}</span><h3>${esc(challenge.program.name)}</h3><p>${esc(challenge.program.tagline)}</p><p>${esc(DIFFICULTIES[challenge.difficulty].label)} · ${challenge.audienceEnabled?'Chat powers on':'Pure skill'} · ${challenge.program.patterns.length} attack patterns</p><p>Attack design: ${esc(challenge.mutationAuthor||'RAIDFORGE')}</p></div><label for="challenge-url">CHALLENGE LINK</label><input class="challenge-link" id="challenge-url" readonly value="${esc(full)}"><div class="modal-actions"><button class="button primary" id="copy-challenge-link">Copy challenge link</button></div><p class="share-note">The link contains the boss and fight settings. Friends can play without an account. Results stay on their device; this is not a global leaderboard.</p>`);$('#copy-challenge-link').onclick=async()=>{try{await navigator.clipboard.writeText(full);this.toast('Challenge link copied. Same boss, same rules.');}catch{$('#challenge-url').select();this.toast('Link selected. Copy it from the field.');}};}catch(e){this.toast(e.message);}}
 incoming(){const hash=location.hash;if(!hash.startsWith('#challenge='))return;try{const challenge=decodeChallenge(hash.slice(11));this.showModal(`<div class="modal-eyebrow">A CHALLENGER HAS BEEN SUMMONED</div><h2>Someone sent you<br>a very angry goose.</h2><div class="challenge-preview"><h3>${esc(challenge.program.name)}</h3><p>${esc(challenge.program.tagline)}</p><p>From ${esc(challenge.author)} · attack design by ${esc(challenge.mutationAuthor)}</p><p>${esc(DIFFICULTIES[challenge.difficulty].label)} · ${challenge.audienceEnabled?'Chat powers on':'Pure skill'}</p></div><p>Accept to equip this boss and its fight settings in your practice workshop. Your run history stays intact.</p><div class="modal-actions"><button class="button primary" id="accept-challenge">Accept challenge →</button><button class="button ghost" id="decline-challenge">Keep my boss</button></div>`);$('#accept-challenge').onclick=()=>{if(this.getMode()!=='practice'){this.toast('Switch to practice before accepting a shared challenge.');return;}this.prefs={difficulty:challenge.difficulty,audienceEnabled:challenge.audienceEnabled};this.savePreferences();this.acceptChallenge(challenge);history.replaceState(null,'',location.pathname+location.search);this.closeModal();this.render();this.toast('Challenge accepted. The same boss. Your next attempt.');};$('#decline-challenge').onclick=()=>{history.replaceState(null,'',location.pathname+location.search);this.closeModal();};}catch(e){history.replaceState(null,'',location.pathname+location.search);this.toast(e.message);}}
 async downloadScorecard(record){await document.fonts.ready;const c=document.createElement('canvas');c.width=1200;c.height=630;const ctx=c.getContext('2d');const s=record.summary||summarizeRun(record);ctx.fillStyle='#121a17';ctx.fillRect(0,0,1200,630);ctx.strokeStyle='#46553d';ctx.lineWidth=2;ctx.strokeRect(24,24,1152,582);ctx.fillStyle='#ff784d';ctx.font='700 29px "Barlow Condensed",sans-serif';ctx.fillText('RAIDFORGE / THE RUN REPORT',64,80);ctx.fillStyle='#e9e6d3';ctx.font='700 80px "Barlow Condensed",sans-serif';ctx.fillText(record.won?'GOOSE. COOKED.':'THE GOOSE WINS.',62,180);ctx.fillStyle='#a4b69f';ctx.font='22px "DM Sans",sans-serif';ctx.fillText(record.boss.slice(0,48),64,225);ctx.font='16px "DM Sans",sans-serif';ctx.fillText(`Attack design by ${(record.creator||'RAIDFORGE').slice(0,60)}`,64,260);const values=[['TIME',clock(record.time)],['SCORE',s.score.toLocaleString()],['ACCURACY',s.accuracy+'%'],['HEARTS',record.health+'/5']];values.forEach(([label,value],i)=>{const x=64+i*225;ctx.fillStyle='#859781';ctx.font='14px "IBM Plex Mono",monospace';ctx.fillText(label,x,355);ctx.fillStyle='#e5ddbd';ctx.font='600 55px "Barlow Condensed",sans-serif';ctx.fillText(value,x,417);});ctx.fillStyle='#e7c18a';ctx.textAlign='right';ctx.font='700 120px "Barlow Condensed",sans-serif';ctx.fillText(s.rank,1110,210);ctx.textAlign='left';ctx.fillStyle='#9daf96';ctx.font='16px "IBM Plex Mono",monospace';ctx.fillText(`${DIFFICULTIES[record.difficulty]?.label||'Standard'} / ${record.audienceEnabled?'Chat powers on':'Pure skill'} / ${record.challengeKey||'Earlier build'}`,64,510);ctx.fillText('Personal run record · Chat builds the boss. You survive it.',64,554);c.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='raidforge-scorecard.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);this.toast('Scorecard downloaded.');},'image/png');}
}
